using System;
using System.Collections.Generic;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Windows.Forms;
using MC2Pack;
namespace Astera {
sealed partial class LibraryForm {
 internal static int AuditMinecraftProfiles(string root){try{
  if(Directory.Exists(root))throw new IOException("Use a fresh Minecraft profiles audit");Directory.CreateDirectory(root);string fixture=Path.Combine(root,"prism");if(NetworkSelfTest.PrismRun(fixture)!=0)throw new IOException(File.ReadAllText(Path.Combine(fixture,"failure.txt")));var release=Engine.Read(Path.Combine(fixture,"full-pack-fixture","release.zip"));string data=Path.Combine(fixture,"Portable Prism");var squared=PrismProfiles.Discover(data).First(p=>File.Exists(Path.Combine(p.GameRoot,"Astera-minecraft-state.json")));var vanilla=PrismProfiles.Create(data,release,true);var checks=new List<string>();
  AssertProfile(!Profiles.Read(vanilla.GameRoot).IsSquared&&Profiles.Read(vanilla.GameRoot).LoaderKind=="vanilla","Vanilla was marked as Minecraft²");
  string cf=Path.Combine(root,"CurseForge"),other=Path.Combine(cf,"Boys Night"),forge=Path.Combine(cf,"Forge Pack");Directory.CreateDirectory(other);Directory.CreateDirectory(forge);string guid=Guid.NewGuid().ToString();File.WriteAllText(Path.Combine(other,"minecraftinstance.json"),Engine.Json.Serialize(new{name="Boys Night",guid=guid,gameVersion="26.3",baseModLoader=new{name="fabric-0.19.5-26.3",minecraftVersion="26.3",forgeVersion="0.19.5"}}));File.WriteAllText(Path.Combine(forge,"minecraftinstance.json"),Engine.Json.Serialize(new{name="Forge Pack",guid=Guid.NewGuid().ToString(),gameVersion="1.20.1",baseModLoader=new{name="forge-47.0.0",minecraftVersion="1.20.1",forgeVersion="47.0.0"}}));AssertProfile(Profiles.All(cf).Count==2&&Profiles.Discover(cf).Count==0,"General pack discovery filters out other loaders or marks them managed");checks.Add("Vanilla and unrelated Fabric/Forge packs are discovered without receiving Minecraft² ownership");
  string uri=CurseForgeLaunch.UriFor(other);AssertProfile(uri=="curseforge://launch-game?instanceId="+guid+"&gameId=432","CurseForge handoff differs from the launcher's generated shortcut");string host=Path.Combine(root,"OverwolfLauncher.exe");File.WriteAllBytes(host,new byte[]{77,90});var command=CurseForgeLaunch.Native(other,host);AssertProfile(!command.UseShellExecute&&command.FileName==host&&command.Arguments=="-launchapp "+CurseForgeLaunch.AppId+" --origin=urlscheme --parameters="+uri,"Native CurseForge dispatch added quotes/encoding or used the shell");checks.Add("CurseForge dispatch targets the registered GUID directly through Overwolf without changing protocol defaults, double encoding or shell interpretation");
  var store=new Store(Path.Combine(root,"state"));store.Settings.Profile=squared.GameRoot;store.Settings.PrismDataRoot=data;store.Settings.PrismExecutable=Path.Combine(fixture,"prismlauncher.exe");store.Settings.CheckOnStart=false;store.Settings.CheckAppOnStart=false;store.Settings.AnimatedEffects=false;store.Settings.UseMinecraftSkin=false;
  using(var form=new LibraryForm(store,new Channel(),true)){form.Location=new Point(-30000,-30000);form.Show();Application.DoEvents();AssertProfile(form.games.Items.Cast<LibraryEntry>().Count(x=>x.Kind==0&&x.Name=="Minecraft")==1,"Library no longer has one Minecraft entry");AssertProfile(form.MinecraftSquaredSelected&&form.heroTitle.Text=="Minecraft²"&&form.modProfileStrip.Visible,"Minecraft² theme/selector missing");var icon=form.MinecraftSelectedIcon();AssertProfile(Object.ReferenceEquals(icon,GameArtwork.MinecraftIcon),"Minecraft² icon missing");
   string art=Path.Combine(root,"profile-art.png");using(var bitmap=new Bitmap(64,32)){using(var g=Graphics.FromImage(bitmap))g.Clear(Color.DarkViolet);bitmap.Save(art);}form.SetMinecraftArtwork(art,false);store.Save();
   // Prevent this isolated selection exercise from checking a live update feed.
   form.SelectMinecraftProfile(Profiles.Read(vanilla.GameRoot));AssertProfile(!form.MinecraftSquaredSelected&&form.heroTitle.Text=="Minecraft"&&form.MinecraftBackground==""&&form.feed==null&&form.plan==null&&!form.updateReady,"Vanilla inherited the Minecraft² theme or update plan");AssertProfile(!Object.ReferenceEquals(form.MinecraftSelectedIcon(),icon),"Vanilla still displays the Minecraft² icon");AssertProfile(Object.ReferenceEquals(form.MinecraftSelectedIcon(),GameArtwork.VanillaMinecraftIcon)&&GameArtwork.VanillaMinecraftIcon.Width==512&&form.heroTitle.MinecraftLogo,"Supplied vanilla icon or header wordmark is missing");using(var backdrop=form.banner.CopyDefaultArtwork())AssertProfile(backdrop!=null&&backdrop.Width==600&&backdrop.Height==375,"Supplied vanilla background is missing or distorted");using(var preview=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(preview,new Rectangle(Point.Empty,preview.Size));preview.Save(Path.Combine(root,"vanilla-selected.png"));}form.CheckMinecraft(true).GetAwaiter().GetResult();form.Download().GetAwaiter().GetResult();form.Install().GetAwaiter().GetResult();AssertProfile(!Directory.Exists(Path.Combine(vanilla.GameRoot,"mods")),"Minecraft² files were installed into vanilla");checks.Add("Profile switching clears pending pack updates, changes title/icon/artwork and prevents Minecraft² checks/install in vanilla");
   form.SelectMinecraftProfile(Profiles.Read(other));AssertProfile(form.heroTitle.Text=="Boys Night"&&!form.MinecraftSquaredSelected&&form.MinecraftBackground=="","Other pack inherited Minecraft² branding");form.SetMinecraftArtwork(art,false);AssertProfile(form.MinecraftBackground==art,"Per-profile background selection failed");store.Save();AssertProfile(store.Settings.MinecraftArtwork.Count==2,"Different profiles share one artwork record");checks.Add("Other packs keep their own name and independent artwork preferences");
   store.Settings.Profile=squared.GameRoot;form.minecraftSelectionPath=null;form.EnsureMinecraftSelection();form.RefreshView();AssertProfile(form.MinecraftSquaredSelected&&form.MinecraftBackground==art&&form.heroTitle.Text=="Minecraft²","Minecraft² artwork was not restored after switching back");AssertProfile(!form.heroTitle.MinecraftLogo,"Vanilla wordmark leaked onto Minecraft²");using(var image=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(image,new Rectangle(Point.Empty,image.Size));image.Save(Path.Combine(root,"minecraft2-selected.png"));}form.Close();}
  var reloaded=new Store(store.Root);AssertProfile(reloaded.Settings.MinecraftArtwork.Count==2,"Profile artwork failed persistence");checks.Add("Returning to Minecraft² restores its theme; artwork choices survive a restart");
  File.WriteAllText(Path.Combine(root,"result.json"),Engine.Json.Serialize(new{Passed=true,Checks=checks,GameLaunched=false,LiveProfileChanged=false,AppSha256=Engine.Hash(Application.ExecutablePath)}));return 0;
 }catch(Exception error){Directory.CreateDirectory(root);File.WriteAllText(Path.Combine(root,"failure.txt"),error.ToString());return 1;}}
 static void AssertProfile(bool value,string message){if(!value)throw new Exception(message);}
}
}
